package com.example.incidentapp.util;
import android.Manifest; import android.content.*; import android.content.pm.PackageManager; import androidx.core.content.ContextCompat; import com.example.incidentapp.model.MensajeResponse; import com.example.incidentapp.repository.UbicacionRepository; import com.google.android.gms.location.*; import retrofit2.*;
public class TecnicoLocationManager { private static TecnicoLocationManager instance; private final Context context; private final FusedLocationProviderClient client; private final UbicacionRepository repo=new UbicacionRepository(); private LocationCallback callback; private boolean compartiendo; public interface Listener{void onMensaje(String m);void onEstado(boolean activo);} private TecnicoLocationManager(Context c){context=c.getApplicationContext();client=LocationServices.getFusedLocationProviderClient(context);} public static synchronized TecnicoLocationManager get(Context c){if(instance==null)instance=new TecnicoLocationManager(c);return instance;} public boolean isCompartiendo(){return compartiendo;} public void iniciar(Listener l){if(ContextCompat.checkSelfPermission(context,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&ContextCompat.checkSelfPermission(context,Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){l.onMensaje("Permiso de ubicación no concedido");return;}LocationRequest req=new LocationRequest.Builder(Priority.PRIORITY_HIGH_ACCURACY,30000).setMinUpdateIntervalMillis(15000).build();callback=new LocationCallback(){@Override public void onLocationResult(LocationResult r){if(r.getLastLocation()==null)return;android.location.Location x=r.getLastLocation();repo.actualizar(x.getLatitude(),x.getLongitude(),x.hasAccuracy()?x.getAccuracy():null,null).enqueue(new Callback<MensajeResponse>(){public void onResponse(Call<MensajeResponse> c,Response<MensajeResponse> rr){if(rr.isSuccessful()){compartiendo=true;l.onEstado(true);}}public void onFailure(Call<MensajeResponse> c,Throwable t){l.onMensaje("No se pudo enviar la ubicación");}});}};client.requestLocationUpdates(req,callback,context.getMainLooper());compartiendo=true;l.onEstado(true);} public void detener(Listener l){if(callback!=null)client.removeLocationUpdates(callback);callback=null;repo.detener().enqueue(new Callback<MensajeResponse>(){public void onResponse(Call<MensajeResponse> c,Response<MensajeResponse> r){compartiendo=false;l.onEstado(false);l.onMensaje("Ubicación compartida desactivada");}public void onFailure(Call<MensajeResponse> c,Throwable t){compartiendo=false;l.onEstado(false);}});} }
